function flattenPages(pages) {
  if (!pages.length || pages.length > 10) throw new Error('Expected 1–10 Famulor response pages.');
  const total = pages[0]?.meta?.pagination?.total;
  if (!Number.isSafeInteger(total) || total < 0) throw new Error('Missing or invalid Famulor result count.');
  if (total > 2000) throw new Error('More than 2,000 records. Narrow the date window.');
  const rows = [];
  let expectedOffset = 0;
  for (const page of pages) {
    if (page.error || !Array.isArray(page.data)) throw new Error('Famulor returned an invalid response. Check the credential and read scope.');
    const p = page.meta?.pagination;
    if (!p || p.total !== total || p.limit !== 200 || p.offset !== expectedOffset || page.data.length > 200) {
      throw new Error('Incomplete or inconsistent Famulor pagination. No destination data was written.');
    }
    rows.push(...page.data);
    expectedOffset += 200;
  }
  if (rows.length !== total) throw new Error('The Famulor scan was incomplete or changed while paging. No destination data was written.');
  const ids = rows.map(row => row?.id);
  if (ids.some(value => typeof value !== 'string' || !value.trim()) || new Set(ids).size !== ids.length) {
    throw new Error('Missing or duplicate record IDs. No destination data was written.');
  }
  return rows;
}
const rows=flattenPages($input.all().map(i=>i.json));

const cfg=$('Build date window').first().json;
const start=Date.parse(cfg.windowStart),end=Date.parse(cfg.windowEnd);
if (!Number.isFinite(start)||!Number.isFinite(end)||end<=start) throw new Error('Invalid configured date range.');

const selected=rows.filter(r=>r.status==='confirmed'&&Date.parse(r.start_at)>=start&&Date.parse(r.start_at)<end).sort((a,b)=>Date.parse(a.start_at)-Date.parse(b.start_at));
const timezone=String(cfg.businessTimezone||'UTC');
const format=new Intl.DateTimeFormat('en-GB',{dateStyle:'medium',timeStyle:'short',timeZone:timezone});
const clean=v=>String(v??'').replace(/[\r\n\t]/g,' ').slice(0,120);
const shown=selected.slice(0,20);
const lines=shown.map(b=>format.format(new Date(b.start_at))+' — '+clean(b.event_type_name||'Appointment')+' — '+(cfg.includeNames?clean(b.invitee_name):'Booking '+clean(b.id)));
const text=['Famulor booking agenda ('+timezone+')','Confirmed appointments: '+selected.length,...(lines.length?lines:['No confirmed appointments in this window.']),...(selected.length>20?['Only the first 20 are shown. Review the full agenda in Famulor.']:[]),'Window: '+cfg.windowStart+' to '+cfg.windowEnd+' (end excluded)'].join('\n');
return [{json:{text,totalBookings:selected.length,displayedBookings:shown.length,displayTimezone:timezone}}];
